import { mkdir, readFile, unlink, writeFile } from "node:fs/promises";
import path from "node:path";

/** Where image bytes live. Bytes never go in PostgreSQL. Swap the implementation for S3-compatible storage in production. */
export interface MediaStorage {
  put(key: string, bytes: Uint8Array): Promise<void>;
  get(key: string): Promise<Uint8Array | null>;
  delete(key: string): Promise<void>;
}

/** Keys are generated by the server (uuid + verified extension). Anything else is refused before touching the disk. */
export const MEDIA_KEY = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.(jpg|png|webp)$/;

export class LocalDiskStorage implements MediaStorage {
  constructor(private readonly dir: string) {}
  private file(key: string): string {
    if (!MEDIA_KEY.test(key)) throw new Error("Invalid media key");
    return path.join(this.dir, key);
  }
  async put(key: string, bytes: Uint8Array): Promise<void> {
    const f = this.file(key);
    await mkdir(this.dir, { recursive: true });
    await writeFile(f, bytes, { flag: "wx" }); // never overwrites an existing file
  }
  async get(key: string): Promise<Uint8Array | null> {
    try { return await readFile(this.file(key)); } catch (e) { if ((e as NodeJS.ErrnoException).code === "ENOENT") return null; throw e; }
  }
  async delete(key: string): Promise<void> {
    try { await unlink(this.file(key)); } catch (e) { if ((e as NodeJS.ErrnoException).code !== "ENOENT") throw e; }
  }
}

const g = globalThis as unknown as { __mediaStorage?: MediaStorage };
export const getMediaStorage = (): MediaStorage => (g.__mediaStorage ??= new LocalDiskStorage(path.resolve(process.env.MEDIA_DIR ?? "./uploads")));
export const setMediaStorage = (s: MediaStorage | undefined): void => { g.__mediaStorage = s; };
